41	 * rules </a> outlined in the Delta Protocol.
42	 */
43	public class DataTypeJsonSerDe {
44	  private static final ObjectMapper OBJECT_MAPPER =
45	      new ObjectMapper()
46	          .registerModule(
47	              new SimpleModule().addSerializer(StructType.class, new StructTypeSerializer()));
48	
49	  private DataTypeJsonSerDe() {}
50	
51	  /**
52	   * Serializes a {@link StructType} to a JSON string
53	   *
54	   * @param structType
55	   * @return
56	   */
57	  public static String serializeStructType(StructType structType) {
58	    try {
59	      return OBJECT_MAPPER.writeValueAsString(structType);
60	    } catch (JsonProcessingException ex) {
61	      throw new KernelException("Could not serialize StructType to JSON", ex);
62	    }
63	  }
64	
65	  /**
66	   * Serializes a {@link DataType} to a JSON string according to the Delta Protocol. TODO: Only
67	   * reason why this API added was due to Flink-Kernel dependency. Currently Flink-Kernel uses the
68	   * Kernel DataType.toJson and Standalone DataType.fromJson to convert between types.
69	   *
70	   * @param dataType
71	   * @return JSON string representing the data type
72	   */
73	  public static String serializeDataType(DataType dataType) {
74	    try {
75	      StringWriter stringWriter = new StringWriter();
76	      JsonGenerator generator = OBJECT_MAPPER.createGenerator(stringWriter);
77	      writeDataType(generator, dataType);
78	      generator.flush();
79	      return stringWriter.toString();
80	    } catch (IOException ex) {
81	      throw new KernelException("Could not serialize DataType to JSON", ex);
82	    }
83	  }
