85	  /**
86	   * Deserializes a JSON string representing a Delta data type to a {@link DataType}.
87	   *
88	   * @param structTypeJson JSON string representing a {@link StructType} data type
89	   */
90	  public static StructType deserializeStructType(String structTypeJson) {
91	    try {
92	      DataType parsedType = parseDataType(OBJECT_MAPPER.reader().readTree(structTypeJson));
93	      if (parsedType instanceof StructType) {
94	        return (StructType) parsedType;
95	      } else {
96	        throw new IllegalArgumentException(
