106	  /**
107	   * Parses a Delta data type from JSON. Data types can either be serialized as strings (for
108	   * primitive types) or as objects (for complex types).
109	   *
110	   * <p>For example:
111	   *
112	   * <pre>
113	   * // Map type field is serialized as:
114	   * {
115	   *   "name" : "f",
116	   *   "type" : {
117	   *     "type" : "map",
118	   *     "keyType" : "string",
119	   *     "valueType" : "string",
120	   *     "valueContainsNull" : true
121	   *   },
122	   *   "nullable" : true,
