package io.delta.kernel.types;

import io.delta.kernel.annotation.Evolving;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;

/**
 * The data type representing {@code geography} type values. Geography represents geodetic
 * (spherical) spatial data and is parameterized by a Spatial Reference System Identifier (SRID) and
 * a geodetic calculation algorithm.
 *
 * <p>Two {@code GeographyType} instances are equal if and only if they have the same SRID and
 * algorithm.
 *
 * @since 4.0.0
 */
@Evolving
public final class GeographyType extends DataType {

  /** The default SRID used when none is specified. */
  public static final String DEFAULT_SRID = "OGC:CRS84";

  /** The default geodetic calculation algorithm used when none is specified. */
  public static final String DEFAULT_ALGORITHM = "spherical";

  /** The set of supported geodetic calculation algorithms. */
  public static final List<String> VALID_ALGORITHMS =
      Arrays.asList("spherical", "vincenty", "thomas", "andoyer", "karney");

  /**
   * @return a {@code GeographyType} with the default SRID ({@value #DEFAULT_SRID}) and default
   *     algorithm ({@value #DEFAULT_ALGORITHM}).
   */
  public static GeographyType ofDefault() {
    return new GeographyType(DEFAULT_SRID, DEFAULT_ALGORITHM);
  }

  /**
   * @param srid the Spatial Reference System Identifier in {@code authority:code} notation.
   * @return a {@code GeographyType} with the given SRID and default algorithm ({@value
   *     #DEFAULT_ALGORITHM}).
   */
  public static GeographyType ofSRID(String srid) {
    return new GeographyType(srid, DEFAULT_ALGORITHM);
  }

  /**
   * @param algorithm the geodetic calculation algorithm; must be one of {@link #VALID_ALGORITHMS}.
   * @return a {@code GeographyType} with the default SRID ({@value #DEFAULT_SRID}) and the given
   *     algorithm.
   */
  public static GeographyType ofAlgorithm(String algorithm) {
    return new GeographyType(DEFAULT_SRID, algorithm);
  }

  private final String srid;
  private final String algorithm;

  /**
   * @param srid the Spatial Reference System Identifier in {@code authority:code} notation.
   * @param algorithm the geodetic calculation algorithm; must be one of {@link #VALID_ALGORITHMS}.
   * @throws IllegalArgumentException if {@code algorithm} is not one of the supported algorithms.
   */
  public GeographyType(String srid, String algorithm) {
    if (!VALID_ALGORITHMS.contains(algorithm)) {
      throw new IllegalArgumentException(
          String.format(
              "Algorithm must be one of: %s", String.join(", ", VALID_ALGORITHMS)));
    }
    this.srid = srid;
    this.algorithm = algorithm;
  }

  /** @return the Spatial Reference System Identifier for this geography type. */
  public String getSrid() {
    return srid;
  }

  /** @return the geodetic calculation algorithm for this geography type. */
  public String getAlgorithm() {
    return algorithm;
  }

  @Override
  public boolean isNested() {
    return false;
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) {
      return true;
    }
    if (!(o instanceof GeographyType)) {
      return false;
    }
    GeographyType that = (GeographyType) o;
    return Objects.equals(srid, that.srid) && Objects.equals(algorithm, that.algorithm);
  }

  @Override
  public int hashCode() {
    return Objects.hash(srid, algorithm);
  }

  @Override
  public String toString() {
    return String.format("Geography(srid=%s, algorithm=%s)", srid, algorithm);
  }
}
